{
  "name": "混合信号示波器",
  "name_en": "Mixed-Signal Oscilloscope",
  "manufacturer": "RIGOL",
  "description": "这是一类台式混合信号示波器，用于采集和显示电压波形，并测量频率、相位等时域参数。它常用于电子实验与调试中观察模拟或数字信号、设置触发条件、调整时基与垂直量程，以及保存波形数据和屏幕截图。",
  "description_en": "This is a bench-top mixed-signal oscilloscope used to acquire and display voltage waveforms and to measure time-domain parameters such as frequency and phase. It is commonly used in electronics labs for observing analog or digital signals, setting trigger conditions, adjusting timebase and vertical scale, and saving waveform data or screen captures.",
  "tag_hints": [
    "oscilloscope",
    "mixed-signal measurement",
    "waveform acquisition",
    "trigger control",
    "timebase adjustment",
    "voltage measurement",
    "frequency measurement",
    "waveform screenshot"
  ],
  "actions": [
    {
      "action_name": "auto-autoscale",
      "description": "自动调整示波器量程与时基以适配输入信号。",
      "description_en": "Automatically adjust the oscilloscope scale and timebase to fit the input signal."
    },
    {
      "action_name": "auto-voltage",
      "description": "测量指定通道的电压相关参数。",
      "description_en": "Measure voltage-related parameters on the specified channel."
    },
    {
      "action_name": "auto-freq",
      "description": "测量指定通道的信号频率。",
      "description_en": "Measure the signal frequency on the specified channel."
    },
    {
      "action_name": "auto-phase",
      "description": "测量两个通道信号之间的相位差。",
      "description_en": "Measure the phase difference between signals on two channels."
    },
    {
      "action_name": "auto-saveChanneltoFile",
      "description": "将指定通道的波形数据保存到文件。",
      "description_en": "Save waveform data from the specified channel to a file."
    },
    {
      "action_name": "auto-setAcquire",
      "description": "设置采样采集方式，包括存储深度和采样模式。",
      "description_en": "Set the acquisition behavior, including memory depth and sampling mode."
    },
    {
      "action_name": "auto-getScreenshoot",
      "description": "保存示波器当前屏幕截图到文件。",
      "description_en": "Save a screenshot of the current oscilloscope display to a file."
    },
    {
      "action_name": "auto-setTimebaseScale",
      "description": "设置水平时基刻度。",
      "description_en": "Set the horizontal timebase scale."
    },
    {
      "action_name": "auto-setChannelOffet",
      "description": "设置通道垂直偏置。",
      "description_en": "Set the channel vertical offset."
    },
    {
      "action_name": "auto-getChannelScale",
      "description": "获取通道垂直刻度。",
      "description_en": "Get the channel vertical scale."
    },
    {
      "action_name": "auto-setChannelScale",
      "description": "设置通道垂直刻度。",
      "description_en": "Set the channel vertical scale."
    },
    {
      "action_name": "auto-getTimebaseScale",
      "description": "获取水平时基刻度。",
      "description_en": "Get the horizontal timebase scale."
    },
    {
      "action_name": "auto-setChannelCouple",
      "description": "设置通道耦合方式。",
      "description_en": "Set the channel coupling mode."
    },
    {
      "action_name": "auto-setTriggerChannel",
      "description": "设置触发源通道。",
      "description_en": "Set the trigger source channel."
    },
    {
      "action_name": "auto-setTriggerLevel",
      "description": "设置触发电平。",
      "description_en": "Set the trigger level."
    },
    {
      "action_name": "auto-setAverageTimes",
      "description": "设置平均采样次数。",
      "description_en": "Set the number of waveform averages."
    },
    {
      "action_name": "auto-setChannelAtte",
      "description": "设置通道探头衰减比。",
      "description_en": "Set the channel probe attenuation factor."
    },
    {
      "action_name": "auto-setChannelUnit",
      "description": "设置通道显示单位。",
      "description_en": "Set the channel display unit."
    },
    {
      "action_name": "auto-getChannelAtte",
      "description": "获取通道探头衰减比。",
      "description_en": "Get the channel probe attenuation factor."
    }
  ]
}

